function overviewPage(){
 const p=graduateProfile(),progress=profileCompletion(),name=(p.name||'').trim().split(/\s+/)[0],hasResume=marketplaceResume().trim().length>=100;
 const bookmarked=jobs.filter(j=>saved.includes(j.id)).slice(0,3),featured=jobs.find(j=>j.id===7)||jobs[0];
 const actions=[['briefcase','Find your next opportunity','Paid projects with a clear scope and a real outcome.','explore','Browse work'],['spark','Build something worth showing','Get a focused project idea for the role you want.','recommend','Explore ideas'],['resume','Make your experience count','See how your resume fits a specific opportunity.','resume','Review resume']];
 return `<div class="dashboard-topline"><div><span class="section-label">YOUR NEXT CHAPTER</span><h1>${name?'Welcome back, '+esc(name)+'.':'Welcome to Nextwork.'}</h1></div><span class="dashboard-date">${new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</span></div><section class="dashboard-hero"><div><span class="hero-eyebrow"><span></span> A LITTLE PROGRESS GOES A LONG WAY</span><h2>Your next opportunity<br>starts with one step.</h2><p>${hasResume?'Your experience is ready to meet the right project. Find work where you can make a contribution.':'Add your experience, find a meaningful project, and build work you can be proud of.'}</p><div><a class="primary" href="#${hasResume?'explore':'profile'}">${hasResume?'Find your next project':'Complete your profile'} ${icon('arrow',17)}</a><a class="hero-secondary" href="#recommend">Get project ideas ${icon('arrow',16)}</a></div></div><a class="dashboard-featured" href="#project/${featured.id}"><div class="dashboard-featured-top">${logo(featured)}<span>PROJECT SPOTLIGHT</span>${icon('arrow',18)}</div><h3>${esc(featured.title)}</h3><p>${esc(featured.c)} · ${esc(featured.cat)}</p><div class="tags">${featured.tags.slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="dashboard-featured-footer"><b>$${featured.pay.toLocaleString()}</b><span>${esc(featured.weeks)} · Remote</span></div></a></section><div class="dashboard-metrics"><a href="#projects" onclick="workTab='applications'">${icon('apps',21)}<span><strong>${applications.length}</strong><small>Application drafts</small></span>${icon('arrow',16)}</a><a href="#projects" onclick="workTab='saved'">${icon('save',21)}<span><strong>${saved.length}</strong><small>Saved opportunities</small></span>${icon('arrow',16)}</a><a href="#profile">${icon('user',21)}<span><strong>${progress.done}<em>/${progress.total}</em></strong><small>Profile details completed</small></span>${icon('arrow',16)}</a></div><div class="dashboard-section-title"><div><span class="section-label">MAKE YOUR NEXT MOVE</span><h2>Where do you want to start?</h2></div></div><div class="dashboard-action-grid">${actions.map(([i,h,d,r,l])=>`<a class="dashboard-action" href="#${r}"><span class="dashboard-action-icon">${icon(i,23)}</span><h3>${h}</h3><p>${d}</p><b>${l} ${icon('arrow',16)}</b></a>`).join('')}</div><div class="dashboard-bottom-grid"><section class="panel dashboard-shortlist"><div class="section-title"><h2>Your shortlist</h2><a class="text-link" href="#projects" onclick="workTab='saved'">View saved ${icon('arrow',15)}</a></div>${bookmarked.length?bookmarked.map(j=>`<a class="dashboard-saved-row" href="#project/${j.id}">${logo(j)}<span><b>${esc(j.title)}</b><small>${esc(j.c)} · $${j.pay.toLocaleString()}</small></span>${icon('arrow',17)}</a>`).join(''):`<div class="shortlist-empty"><span>${icon('save',25)}</span><div><h3>Keep the good ones close.</h3><p>Save an opportunity as you browse. Your shortlist will be waiting here.</p><a class="text-link" href="#explore">Find something worth saving ${icon('arrow',14)}</a></div></div>`}</section><section class="panel dashboard-readiness"><span class="section-label">GET READY TO APPLY</span><h2>A little setup goes a long way.</h2>${[[Boolean(p.name&&p.education),'Introduce yourself','profile'],[hasResume,'Add your resume','profile'],[Boolean(p.skills),'Show your skills','profile']].map(([done,label,route])=>`<a href="#${route}"><span class="readiness-check ${done?'done':''}">${done?icon('check',14):icon('plus',14)}</span>${label}<small>${done?'Done':'Add'}</small></a>`).join('')}<a class="text-link" href="#submissions">Open organization applications ${icon('arrow',14)}</a></section></div>`;
}
